import math


def frame_rms(samples, frame, hop):
    values = []
    index = 0
    while index + frame <= len(samples):
        window = samples[index:index + frame]
        values.append(math.sqrt(sum(value * value for value in window) / frame))
        index += hop
    return values


def voiced_mask(rms, ratio=0.15):
    if not rms:
        return []
    low, high = min(rms), max(rms)
    threshold = low + ratio * (high - low)
    return [value > threshold for value in rms]


def to_segments(mask, hop, sample_rate):
    segments = []
    start = None
    for index, voiced in enumerate(mask):
        if voiced and start is None:
            start = index
        elif not voiced and start is not None:
            segments.append((start * hop / sample_rate, index * hop / sample_rate))
            start = None
    if start is not None:
        segments.append((start * hop / sample_rate, len(mask) * hop / sample_rate))
    return segments


def merge_segments(segments, min_gap):
    merged = []
    for start, end in segments:
        if merged and start - merged[-1][1] < min_gap:
            merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def speech_fraction(segments, duration):
    if duration <= 0:
        raise ValueError("duration must be positive")
    return sum(end - start for start, end in segments) / duration


def align_words(segment):
    words = segment["text"].split()
    if not words:
        return []
    total = sum(len(word) for word in words)
    span = segment["end"] - segment["start"]
    aligned = []
    edge = segment["start"]
    for index, word in enumerate(words):
        width = span * len(word) / total
        end = segment["end"] if index == len(words) - 1 else edge + width
        aligned.append({"word": word, "start": edge, "end": end})
        edge = end
    return aligned


def assign_speakers(words, turns, unknown="UNKNOWN"):
    labelled = []
    for word in words:
        middle = (word["start"] + word["end"]) / 2
        speaker = unknown
        for start, end, label in turns:
            if start <= middle < end:
                speaker = label
                break
        labelled.append({**word, "speaker": speaker})
    return labelled


def lazy_transcribe(chunks, worker):
    def generate():
        for chunk in chunks:
            yield worker(chunk)
    return generate()
